Section RF.
  Context (fx : FPState).
  Variables (R : bvmap 5 word) (M : word -> option byte) (S can : Z).
  Hypothesis G1 : getr R (reg 1) = Z_to_bv 64 715920.        (* [comment removed for export] *)
  Hypothesis G2 : getr R (reg 2) = Z_to_bv 64 S.
  Hypothesis G10 : getr R (reg 10) = Z_to_bv 64 1422752.      (* [comment removed for export] *)
  Hypothesis G11 : getr R (reg 11) = Z_to_bv 64 110059.      (* [comment removed for export] *)
